import RNA
import random

target = ".......((((.((((.(((.(((....))).(((.(((....))).(((.(((....))).(((.(((....))).(((......))).))).))).))).))).(....).)))).((((...(((.(((...((....))........))).(((.(((....)))(((....)))(((....)))))).)))...((((.(....).(((.(((.(((.(((.(((...(((....))).))).(((....))).))).(((....))).))).(((....))).))).((((((....)))(((....))).(((....)))))).))).))))...)))).))))...."
n = len(target)

pair_map = [None]*n
stack = []
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j = stack.pop()
        pair_map[j]=i
        pair_map[i]=j

units = {
 (21,30): "UGGGUCCCCA",
 (36,45): "UGGGUCCCCA",
 (51,60): "UGGGUCCCCA",
 (66,75): "UGGGUCCCCA",
 (77,88): "CUCAUCCCGGAG",
 (106,111): "CUGGUG",
 (129,153): "GGCGCCCCGAAAGGACAGAUAAGCC",
 (159,168): "UGGGUCCCCA",
 (169,178): "UGGGUCCCCA",
 (179,188): "UGGGUCCCCA",
 (204,209): "CUGGUG",
 (227,246): "GCUGUGACCAAGGGGUAGGC",
 (248,257): "UGGGUCCCCA",
 (263,272): "UGGGUCCCCA",
 (278,287): "UGGGUCCCCA",
 (296,305): "UGGGUCCCCA",
 (306,315): "UGGGUCCCCA",
 (317,326): "UGGGUCCCCA",
}

def build_from_units():
    seq = ['A'] * n
    for (s,e), u in units.items():
        for i,c in enumerate(u):
            seq[s+i] = c
    for i,c in enumerate(target):
        if seq[i]=='A':
            if c=='(':
                seq[i]='G'
            elif c==')':
                seq[i]='C'
    return ''.join(seq)

def fold(seq):
    fc = RNA.fold_compound(seq)
    mfe, _ = fc.mfe()
    return mfe

def pm_of(struct):
    pm = [None]*n
    st=[]
    for i,c in enumerate(struct):
        if c=='(': st.append(i)
        elif c==')':
            if st:
                j=st.pop(); pm[j]=i; pm[i]=j
    return pm

target_pm = pm_of(target)
target_pairs = set()
for i in range(n):
    if target_pm[i] is not None and i<target_pm[i]:
        target_pairs.add((i,target_pm[i]))

def score(seq):
    mfe = fold(seq)
    mfe_pm = pm_of(mfe)
    mfe_pairs = set()
    for i in range(n):
        if mfe_pm[i] is not None and i<mfe_pm[i]:
            mfe_pairs.add((i,mfe_pm[i]))
    d = len(mfe_pairs ^ target_pairs)
    return d, mfe_pm

seq = build_from_units()
d, mfe_pm = score(seq)
print("start bp_dist:", d, flush=True)

best_seq = seq
best_d = d

random.seed(42)
for it in range(300000):
    if d==0:
        break
    wrong = []
    for i in range(n):
        in_tgt = pair_map[i] is not None
        in_mfe = mfe_pm[i] is not None
        if in_tgt and in_mfe:
            if pair_map[i] != mfe_pm[i]:
                wrong.append(i)
        elif in_tgt != in_mfe:
            wrong.append(i)
    if not wrong:
        break
    i = random.choice(wrong)
    new = list(seq)
    r = random.random()
    if pair_map[i] is not None:
        j = pair_map[i]
        if r < 0.5:
            new[i], new[j] = 'G','C'
        elif r < 0.8:
            new[i], new[j] = 'C','G'
        else:
            new[i], new[j] = 'G','U'
    else:
        # should be unpaired - disrupt
        new[i] = random.choice(['A','A','A','U','C'])
    newseq = ''.join(new)
    nd, nmfe_pm = score(newseq)
    if nd <= d:
        if nd < d or random.random() < 0.25:
            seq = newseq
            d = nd
            mfe_pm = nmfe_pm
            if nd < best_d:
                best_d = nd
                best_seq = newseq
    if it % 10000 == 0:
        print(f"it {it} d={d} best={best_d}", flush=True)

print("FINAL d:", d, "best:", best_d, flush=True)
print("BEST_SEQ:", best_seq, flush=True)
